const nodes=[...document.querySelectorAll('[data-i]')];const english=Object.fromEntries(nodes.map(n=>[n.dataset.i,n.innerHTML]));
function setLanguage(lang){if(!['en','fr','de'].includes(lang))lang='en';document.documentElement.lang=lang;nodes.forEach(n=>{n.innerHTML=(lang==='en'?english:translations[lang])[n.dataset.i]||english[n.dataset.i]});document.querySelectorAll('[data-lang]').forEach(b=>{b.classList.toggle('active',b.dataset.lang===lang);b.setAttribute('aria-pressed',String(b.dataset.lang===lang))});document.querySelector('.ticket-route strong').textContent={en:'Today',fr:'Aujourd’hui',de:'Heute'}[lang];document.querySelector('.menu').setAttribute('aria-label',{en:'Toggle navigation',fr:'Afficher le menu',de:'Menü öffnen'}[lang]);try{localStorage.setItem('tejis-language',lang)}catch{}}
document.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',()=>setLanguage(b.dataset.lang)));

// Reveal each course-detail card once as it enters the viewport.
const detailCards = [...document.querySelectorAll('.detail-card')];
const detailMotionPreference = window.matchMedia('(prefers-reduced-motion: reduce)');
let detailObserver;
function configureDetailMotion() {
  detailObserver?.disconnect();
  detailCards.forEach(card => card.classList.remove('detail-motion-ready'));
  if (detailMotionPreference.matches || !('IntersectionObserver' in window)) return;
  detailObserver = new IntersectionObserver(entries => entries.forEach(entry => {
    if (!entry.isIntersecting) return;
    entry.target.classList.add('details-revealed');
    detailObserver.unobserve(entry.target);
  }), { threshold: .1 });
  detailCards.forEach((card,index) => {
    card.style.setProperty('--detail-delay', `${index * 130}ms`);
    card.classList.add('detail-motion-ready');
    detailObserver.observe(card);
  });
}
configureDetailMotion();
detailMotionPreference.addEventListener('change', configureDetailMotion);

const closingCopy = document.querySelector('.contact-copy');
let closingObserver;
function configureClosingMotion() {
  closingObserver?.disconnect();
  if (!closingCopy) return;
  closingCopy.classList.remove('contact-motion-ready');
  if (detailMotionPreference.matches || !('IntersectionObserver' in window)) return;
  closingCopy.classList.add('contact-motion-ready');
  closingObserver = new IntersectionObserver(entries => {
    if (!entries.some(entry => entry.isIntersecting)) return;
    closingCopy.classList.add('contact-entered');
    closingObserver.disconnect();
  }, {threshold:.15});
  closingObserver.observe(closingCopy);
}
configureClosingMotion();
detailMotionPreference.addEventListener('change', configureClosingMotion);

const aboutPanels=[...document.querySelectorAll('#about .about-visual,#about .about-copy')];
let aboutObserver;
function configureAboutMotion() {
  aboutObserver?.disconnect();
  aboutPanels.forEach(panel=>panel.classList.remove('about-panel-ready'));
  if(detailMotionPreference.matches||!('IntersectionObserver' in window))return;
  aboutObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{
    if(!entry.isIntersecting)return;
    entry.target.classList.add('about-panel-entered');
    aboutObserver.unobserve(entry.target);
  }),{threshold:.12});
  aboutPanels.forEach(panel=>{panel.classList.add('about-panel-ready');aboutObserver.observe(panel);});
}
configureAboutMotion();
detailMotionPreference.addEventListener('change',configureAboutMotion);

const closingSections=[...document.querySelectorAll('#references .section-heading,#references .reference-card,#references > details,.faq-heading,.faq-list details,.contact-info,footer')];
let closingSectionsObserver;
function configureClosingSectionsMotion() {
  closingSectionsObserver?.disconnect();
  closingSections.forEach(element=>element.classList.remove('closing-motion-ready'));
  if(detailMotionPreference.matches||!('IntersectionObserver' in window))return;
  closingSectionsObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{
    if(!entry.isIntersecting)return;
    entry.target.classList.add('closing-in-view');
    closingSectionsObserver.unobserve(entry.target);
  }),{threshold:.08});
  closingSections.forEach((element,index)=>{
    element.style.setProperty('--closing-delay',`${(index%4)*70}ms`);
    element.classList.add('closing-motion-ready');
    closingSectionsObserver.observe(element);
  });
}
configureClosingSectionsMotion();
detailMotionPreference.addEventListener('change',configureClosingSectionsMotion);
const menu=document.querySelector('.menu'),nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open))});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}));try{setLanguage(localStorage.getItem('tejis-language')||'en')}catch{setLanguage('en')}
